  processTemplate(template: string): string {
    if (!this.selectedNewsForShare || !template) return template;
    
    let processedTemplate = template;
    
    // Replace template variables with actual news data
    processedTemplate = processedTemplate.replace(/{{title}}/g, this.selectedNewsForShare.title || '');
    processedTemplate = processedTemplate.replace(/{{subtitle}}/g, this.selectedNewsForShare.sub_title || '');
    processedTemplate = processedTemplate.replace(/{{description}}/g, 
      this.selectedNewsForShare.description ? 
        (this.selectedNewsForShare.description.length > 200 ? 
          this.selectedNewsForShare.description.substring(0, 200) + '...' : 
          this.selectedNewsForShare.description) : '');
    processedTemplate = processedTemplate.replace(/{{sourceLink}}/g, this.selectedNewsForShare.sourceLink || '');
    processedTemplate = processedTemplate.replace(/{{category}}/g, this.selectedNewsForShare.category || '');
    processedTemplate = processedTemplate.replace(/{{location}}/g, 
      `${this.selectedNewsForShare.mandal || ''}, ${this.selectedNewsForShare.district || ''}, ${this.selectedNewsForShare.state || ''}`.replace(/^, |, $/g, ''));
    processedTemplate = processedTemplate.replace(/{{reportedBy}}/g, 
      this.selectedNewsForShare.reportedBy?.name || this.selectedNewsForShare.reportedBy || '');
    
    return processedTemplate;
  }

  getWhatsAppMessage(): string {
    if (!this.selectedNewsForShare) return '';
    
    let message = '';
    
    // Add news title
    message += `📰 ${this.selectedNewsForShare.title}\n\n`;
    
    // Add subtitle if available
    if (this.selectedNewsForShare.sub_title) {
      message += `${this.selectedNewsForShare.sub_title}\n\n`;
    }
    
    // Add description (truncated if too long)
    if (this.selectedNewsForShare.description) {
      const description = this.selectedNewsForShare.description.length > 200 
        ? this.selectedNewsForShare.description.substring(0, 200) + '...'
        : this.selectedNewsForShare.description;
      message += `${description}\n\n`;
    }
    
    // Add source link if available
    if (this.selectedNewsForShare.sourceLink) {
      message += `🔗 Read more: ${this.selectedNewsForShare.sourceLink}\n\n`;
    }
    
    // Add footer
    message += '📱 Shared via Neti Charithra News';
    
    return message;
  }

