  /**
   * Captures the template image container as a base64 image with proper image handling
   * @returns Promise<string> - Base64 encoded image data
   */
  async captureTemplateAsImage(): Promise<string> {
    try {
      const templateElement = document.getElementById('templateImageContainer');
      
      if (!templateElement) {
        throw new Error('Template container not found');
      }

      console.log('Starting template capture with image fixes...');
      
      // Create a clone to modify without affecting the original
      const clonedElement = templateElement.cloneNode(true) as HTMLElement;
      
      // Preserve computed styles by copying them as inline styles
      this.copyComputedStylesToInline(templateElement, clonedElement);
      
      // Fix background image path and convert to proper img element
      await this.fixBackgroundImages(clonedElement);
      
      // Fix content images CORS issues
      await this.fixContentImages(clonedElement);
      
      // Temporarily add clone to DOM for capture (keep it visible but off-screen)
      clonedElement.style.position = 'absolute';
      clonedElement.style.left = '-9999px';
      clonedElement.style.top = '0';
      clonedElement.style.zIndex = '-1000';
      clonedElement.style.visibility = 'visible'; // Ensure visibility
      document.body.appendChild(clonedElement);
      
      try {
        // Wait for images to load
        await new Promise(resolve => setTimeout(resolve, 2000));
        
        // Capture with improved settings for better external image handling and styling
        const canvas = await html2canvas(clonedElement, {
          allowTaint: true,
          useCORS: true,
          logging: true, // Enable logging to see what's happening
          width: clonedElement.offsetWidth,
          height: clonedElement.offsetHeight
        });

        console.log('Canvas created successfully:', canvas.width, 'x', canvas.height);
        
        // Convert to base64
        const base64Image = canvas.toDataURL('image/png', 0.9);
        console.log('Template captured successfully, size:', base64Image.length);
        
        return base64Image;
        
      } finally {
        // Clean up clone
        document.body.removeChild(clonedElement);
      }
      
    } catch (error) {
      console.error('Error capturing template as image:', error);
      this.messageService.showError('Failed to capture template image');
      throw error;
    }
  }

  /**
   * Fixes background image path issues and converts to img elements
   */
  private async fixBackgroundImages(element: HTMLElement): Promise<void> {
    const elementsWithBg = element.querySelectorAll('[style*="background-image"]');
    
    for (const el of Array.from(elementsWithBg)) {
      const htmlEl = el as HTMLElement;
      const style = htmlEl.style.backgroundImage;
      
      if (style && style !== 'none') {
        // Extract URL and fix path
        const urlMatch = style.match(/url\(["']?([^"'\)]+)["']?\)/);
        if (urlMatch && urlMatch[1]) {
          let imageUrl = urlMatch[1];
          
          // Fix relative path issue - handle both relative and absolute paths
          if (imageUrl.startsWith('assets/')) {
            imageUrl = `http://localhost:4200/${imageUrl}`;
          } else if (imageUrl.startsWith('/assets/')) {
            imageUrl = `http://localhost:4200${imageUrl}`;
          } else if (!imageUrl.startsWith('http')) {
            // Handle any other relative paths
            imageUrl = `http://localhost:4200/${imageUrl.replace(/^\/+/, '')}`;
          }
          
          console.log('Processing background image:', imageUrl);
          
          try {
            // Convert to base64
            const base64Image = await this.imageToBase64(imageUrl);
            
            // Create img element to replace background
            const imgElement = document.createElement('img');
            imgElement.src = base64Image;
            imgElement.style.width = '100%';
            imgElement.style.height = '100%';
            imgElement.style.objectFit = 'cover';
            imgElement.style.position = 'absolute';
            imgElement.style.top = '0';
            imgElement.style.left = '0';
            imgElement.style.zIndex = '-1';
            
            // Remove background and add img
            htmlEl.style.backgroundImage = 'none';
            htmlEl.style.position = 'relative';
            htmlEl.insertBefore(imgElement, htmlEl.firstChild);
            
            console.log('✅ Background image converted successfully');
          } catch (error) {
            console.error('❌ Failed to convert background image:', error);
          }
        }
      }
    }
  }

  /**
   * Fixes CORS issues with content images by setting proper attributes
   */
  private async fixContentImages(element: HTMLElement): Promise<void> {
    const images = element.querySelectorAll('img');
    console.log(`Found ${images.length} content images to process`);
    
    for (let i = 0; i < images.length; i++) {
      const img = images[i] as HTMLImageElement;
      const originalSrc = img.src;
      console.log(`Processing content image: ${originalSrc}`);
      
      // Check if it's an S3 or external image
      const isS3Image = originalSrc.includes('amazonaws.com') || originalSrc.includes('s3.');
      
      if (isS3Image) {
        console.log(`🌐 Detected S3 image, setting CORS attributes`);
        
        // Set crossOrigin attribute to allow html2canvas to handle it
        img.crossOrigin = 'anonymous';
        
        // Force reload the image with CORS headers
        const currentSrc = img.src;
        img.src = '';
        img.src = currentSrc;
        
        console.log(`✅ S3 image configured for CORS: ${originalSrc}`);
      } else {
        // Local image - should work fine
        console.log(`✅ Local image, no CORS configuration needed`);
      }
    }
    
    // Wait a bit for images to reload with CORS headers
    await new Promise(resolve => setTimeout(resolve, 1000));
  }

