  /**
   * Converts any image URL to base64 with improved CORS handling
   */
  private async imageToBase64(imageUrl: string): Promise<string> {
    return new Promise((resolve, reject) => {
      // For S3 or external images, always use CORS from the start
      const isExternalImage = imageUrl.includes('amazonaws.com') || 
                             imageUrl.includes('s3.') || 
                             (!imageUrl.startsWith('http://localhost') && imageUrl.startsWith('http'));
      
      const img = new Image();
      
      if (isExternalImage) {
        img.crossOrigin = 'anonymous';
        console.log('Loading external image with CORS:', imageUrl);
      } else {
        console.log('Loading local image:', imageUrl);
      }
      
      img.onload = () => {
        try {
          const canvas = document.createElement('canvas');
          const ctx = canvas.getContext('2d');
          
          if (!ctx) {
            reject(new Error('Canvas context not available'));
            return;
          }
          
          canvas.width = img.width;
          canvas.height = img.height;
          ctx.drawImage(img, 0, 0);
          
          const base64 = canvas.toDataURL('image/png');
          console.log('✅ Successfully converted image to base64');
          resolve(base64);
        } catch (error) {
          console.error('❌ Canvas tainted error:', error);
          // If CORS fails, try to use a proxy or fallback
          if (isExternalImage) {
            reject(new Error(`CORS error: Cannot convert external image to base64. Image URL: ${imageUrl}`));
          } else {
            reject(error);
          }
        }
      };
      
      img.onerror = (error) => {
        console.error('❌ Image load error:', error);
        reject(new Error(`Failed to load image: ${imageUrl}`));
      };
      
      img.src = imageUrl;
    });
  }

