  /**
   * Converts background images to actual img elements for better html2canvas compatibility
   * @param element - The element to process
   */
  private async convertBackgroundImagesToImg(element: HTMLElement): Promise<void> {
    const elementsWithBgImage = element.querySelectorAll('[style*="background-image"]');
    
    for (const el of Array.from(elementsWithBgImage)) {
      const htmlEl = el as HTMLElement;
      const computedStyle = window.getComputedStyle(htmlEl);
      const bgImage = computedStyle.backgroundImage;
      
      if (bgImage && bgImage !== 'none') {
        // Extract URL from background-image CSS property
        const urlMatch = bgImage.match(/url\(["']?([^"'\)]+)["']?\)/);
        if (urlMatch && urlMatch[1]) {
          const imageUrl = urlMatch[1];
          
          try {
            // Convert the image to base64 to avoid CORS issues
            const base64Image = await this.convertImageToBase64(imageUrl);
            
            // Create an img element
            const imgElement = document.createElement('img');
            imgElement.src = base64Image;
            imgElement.style.width = '100%';
            imgElement.style.height = '100%';
            imgElement.style.objectFit = computedStyle.backgroundSize || 'cover';
            imgElement.style.objectPosition = computedStyle.backgroundPosition || 'center';
            imgElement.style.position = 'absolute';
            imgElement.style.top = '0';
            imgElement.style.left = '0';
            imgElement.style.zIndex = '-1';
            
            // Remove background image and add the img element
            htmlEl.style.backgroundImage = 'none';
            htmlEl.style.position = 'relative';
            htmlEl.insertBefore(imgElement, htmlEl.firstChild);
            
            console.log('Converted background image to img element:', imageUrl);
          } catch (error) {
            console.error('Failed to convert background image:', imageUrl, error);
          }
        }
      }
    }
  }

  /**
   * Converts an image URL to base64 to avoid CORS issues
   * @param imageUrl - The image URL to convert
   * @returns Promise<string> - Base64 encoded image
   */
  private async convertImageToBase64(imageUrl: string): Promise<string> {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        
        if (!ctx) {
          reject(new Error('Failed to get canvas context'));
          return;
        }
        
        canvas.width = img.width;
        canvas.height = img.height;
        
        ctx.drawImage(img, 0, 0);
        
        try {
          const base64 = canvas.toDataURL('image/png');
          resolve(base64);
        } catch (error) {
          reject(error);
        }
      };
      
      img.onerror = () => {
        reject(new Error(`Failed to load image: ${imageUrl}`));
      };
      
      img.src = imageUrl;
    });
  }

  /**
   * Waits for all images within an element to load
   * @param element - The container element
   */
  private async waitForImagesToLoad(element: HTMLElement): Promise<void> {
    const images = element.querySelectorAll('img');
    const imagePromises: Promise<void>[] = [];

    images.forEach((img: HTMLImageElement) => {
      if (img.complete) {
        return; // Image already loaded
      }

      const promise = new Promise<void>((resolve, reject) => {
        const timeout = setTimeout(() => {
          console.warn('Image load timeout:', img.src);
          resolve(); // Resolve anyway to not block the capture
        }, 10000);

        img.onload = () => {
          clearTimeout(timeout);
          console.log('Image loaded:', img.src);
          resolve();
        };

        img.onerror = () => {
          clearTimeout(timeout);
          console.error('Image failed to load:', img.src);
          resolve(); // Resolve anyway to not block the capture
        };
      });

      imagePromises.push(promise);
    });

    await Promise.all(imagePromises);
    console.log('All images processed for capture');
  }

